## Why This Is Asked

This question introduces offline-first syncing with conflict resolution, a common beginner E2E scenario that tests practical skills with service workers, IndexedDB, and test orchestration across browser contexts.

## Key Concepts

- Offline-first architecture and PWA fundamentals
- Service workers for caching and network interception
- IndexedDB for local persistent storage
- Test isolation using multiple browser contexts
- Conflict resolution strategies (last-write-wins, merge, CRDT)
- Idempotent sync operations and data seeding

## Code Example

```javascript
const { test, expect } = require('@playwright/test');

test.describe('Note-taking PWA E2E', () => {
  let contextA, contextB, pageA, pageB;

  test.beforeEach(async ({ browser }) => {
    // Create two isolated browser contexts to simulate two devices
    contextA = await browser.newContext();
    contextB = await browser.newContext();
    pageA = await contextA.newPage();
    pageB = await contextB.newPage();

    // Seed initial notes into IndexedDB for both contexts
    await seedInitialNotes(pageA);
    await seedInitialNotes(pageB);
  });

  test('syncs notes without duplicates after going offline/online', async () => {
    // Step 1: Simulate offline mode on Device A
    await pageA.route('**/*', route => route.abort('offline'));

    // Step 2: Create and edit a note while offline
    const noteId = await createNoteOffline(pageA, 'Original Title', 'Original Content');
    await editNoteOffline(pageA, noteId, 'Updated Title', 'Updated Content');

    // Step 3: Bring Device B online and make a conflicting edit
    await pageB.goto('/');
    await pageB.waitForSelector('[data-testid="note-list"]');
    await editNote(pageB, noteId, 'Conflicting Title', 'Conflicting Content');

    // Step 4: Restore connectivity on Device A to trigger sync
    await pageA.unrouteAll();

    // Step 5: Verify sync completes within 10 seconds
    await expect(pageA.locator('[data-testid="sync-status"]')).toHaveText('Synced', { timeout: 10000 });

    // Step 6: Assert no duplicates and correct timestamps
    const notes = await getAllNotes(pageA);
    const duplicateNotes = notes.filter(n => n.title === 'Updated Title');

    expect(duplicateNotes).toHaveLength(1);
    expect(notes[0].updatedAt).toBeGreaterThan(notes[0].createdAt);
  });

  async function seedInitialNotes(page) {
    await page.evaluate(() => {
      const request = indexedDB.open('NotesDB', 1);
      request.onupgradeneeded = (event) => {
        const db = event.target.result;
        if (!db.objectStoreNames.contains('notes')) {
          db.createObjectStore('notes', { keyPath: 'id' });
        }
      };
      request.onsuccess = (event) => {
        const db = event.target.result;
        const tx = db.transaction('notes', 'readwrite');
        const store = tx.objectStore('notes');
        store.put({ id: 'note-1', title: 'Welcome', content: 'Welcome to the app!', createdAt: Date.now(), updatedAt: Date.now() });
      };
    });
  }

  async function createNoteOffline(page, title, content) {
    return await page.evaluate(([t, c]) => {
      return new Promise((resolve) => {
        const request = indexedDB.open('NotesDB', 1);
        request.onsuccess = (event) => {
          const db = event.target.result;
          const tx = db.transaction('notes', 'readwrite');
          const store = tx.objectStore('notes');
          const id = 'note-' + Date.now();
          store.put({ id, title: t, content: c, createdAt: Date.now(), updatedAt: Date.now() });
          tx.oncomplete = () => resolve(id);
        };
      });
    }, [title, content]);
  }

  async function editNote(page, id, title, content) {
    await page.click(`[data-testid="note-${id}"]`);
    await page.fill('[data-testid="title-input"]', title);
    await page.fill('[data-testid="content-input"]', content);
    await page.click('[data-testid="save-button"]');
  }

  async function getAllNotes(page) {
    return await page.evaluate(() => {
      return new Promise((resolve) => {
        const request = indexedDB.open('NotesDB', 1);
        request.onsuccess = (event) => {
          const db = event.target.result;
          const tx = db.transaction('notes', 'readonly');
          const store = tx.objectStore('notes');
          const getAll = store.getAll();
          getAll.onsuccess = () => resolve(getAll.result);
        };
      });
    });
  }
});
```

## How to Verify End-to-End Success

1. **Tooling**: Playwright with isolated browser contexts provides proper data isolation while simulating real multi-device scenarios
2. **Data Isolation**: Each browser context has its own IndexedDB instance, ensuring tests don't interfere with each other
3. **Success Criteria**: 
   - Notes sync within 10 seconds of connectivity restored
   - No duplicate entries exist after sync
   - Timestamps are preserved and accurate
   - Conflict resolution produces consistent results

## Why This Is Asked

Tests for real-time collaboration systems must handle offline edits, eventual consistency, and deterministic merges. This question evaluates your ability to architect an end-to-end flow that exercises offline queues, CRDT-based merging, and version history while ensuring test isolation and reproducibility.

## Key Concepts

- Offline-first collaboration with optimistic UI updates
- CRDT-based merge algorithms ensuring deterministic outcomes
- Test data isolation using per-test seeds and unique identifiers
- Server-sync mocks with controlled timing for deterministic test results

## Code Example

```javascript
// Setup two Playwright contexts for concurrent user simulation
const contextA = await browser.newContext();
const contextB = await browser.newContext();
const pageA = await contextA.newPage();
const pageB = await contextB.newPage();

// Seed a shared base document
const docId = await seedDocument({ content: 'Initial paragraph.' });

// Simulate offline for both users
await setNetworkOffline(pageA);
await setNetworkOffline(pageB);

// User A edits the paragraph
await pageA.goto(`/doc/${docId}`);
await pageA.locator('.editor').fill('User A edited this.');

// User B edits the same paragraph offline
await pageB.goto(`/doc/${docId}`);
await pageB.locator('.editor').fill('User B edited that.');

// Reconnect both users to trigger CRDT sync
await setNetworkOnline(pageA);
await setNetworkOnline(pageB);

// Wait for sync completion
await expect(pageA.locator('.editor')).toHaveText('Expected merged content');
await expect(pageB.locator('.editor')).toHaveText('Expected merged content');

// Verify idempotent replay
const versionBefore = await getDocumentVersion(docId);
await triggerSyncAgain(pageA);
const versionAfter = await getDocumentVersion(docId);
expect(versionAfter).toBe(versionBefore);

// Verify version history
const history = await getVersionHistory(docId);
expect(history).toContain('User A edited this.');
expect(history).toContain('User B edited that.');
```

## Why This Question Is Asked
This question evaluates the ability to design reproducible, scalable end-to-end tests that validate strict data isolation in a real-time, tenant-separated system. It also tests understanding of failure scenarios that expose flaky caching or routing logic.

## Key Concepts
- End-to-end test orchestration across ingestion, broker, cache, storage, and UI
- Per-tenant data isolation and security boundaries
- Real-time WebSocket delivery and latency budgets
- Fault injection and resilience under peak load
- Telemetry, tracing, and reproducibility

## Code Example

```javascript
// Seed data and tenant configuration
const tenants = [
  { id: 'tenant-a', name: 'Acme Corp', apiKey: 'key_a_xxx' },
  { id: 'tenant-b', name: 'Beta Inc', apiKey: 'key_b_xxx' },
  { id: 'tenant-c', name: 'Gamma LLC', apiKey: 'key_c_xxx' },
  { id: 'tenant-d', name: 'Delta Co', apiKey: 'key_d_xxx' },
  { id: 'tenant-e', name: 'Epsilon Ltd', apiKey: 'key_e_xxx' },
];

// Traffic pattern: 20k events/second per tenant
const EVENTS_PER_SECOND = 20000;
const DURATION_SECONDS = 60;

async function ingestEvents(tenant, emitFn) {
  const interval = 1000 / EVENTS_PER_SECOND;
  for (let i = 0; i < DURATION_SECONDS * EVENTS_PER_SECOND; i++) {
    emitFn({
      tenantId: tenant.id,
      eventId: uuid(),
      timestamp: Date.now(),
      payload: { value: Math.random(), tag: tenant.id },
    });
    await sleep(interval);
  }
}

// Fault injection: broker drop
async function injectBrokerDrop(broker, dropPercent = 5) {
  const originalPublish = broker.publish.bind(broker);
  broker.publish = async (topic, msg) => {
    if (Math.random() * 100 < dropPercent) return; // drop
    return originalPublish(topic, msg);
  };
}

// Fault injection: cache eviction
function evictCacheKey(cache, keyPattern) {
  const keys = cache.keys().filter(k => keyPattern.test(k));
  keys.forEach(k => cache.delete(k));
}

// Verification: detect cross-tenant leakage
async function verifyIsolation(dashboard, expectedTenantId) {
  const messages = await dashboard.getReceivedMessages();
  for (const msg of messages) {
    if (msg.tenantId !== expectedTenantId) {
      throw new Error(`CROSS-TENANT LEAK: ${msg.tenantId} seen on ${expectedTenantId}'s dashboard`);
    }
  }
}

// Latency verification
function verifyLatency(msgTimestamp, receiveTimestamp) {
  const latency = receiveTimestamp - msgTimestamp;
  if (latency > 2000) {
    throw new Error(`LATENCY BREACH: ${latency}ms exceeds 2s threshold`);
  }
  return latency;
}

// Main test orchestration
async function runE2ETest() {
  const broker = new MessageBroker();
  const cache = new TenantCache();
  const storage = new TenantStorage();
  const dashboards = {};

  // Setup WebSocket dashboards per tenant
  for (const tenant of tenants) {
    dashboards[tenant.id] = new WebSocketDashboard({
      authToken: tenant.apiKey,
      onMessage: (msg, ts) => {
        verifyIsolation(dashboards[tenant.id], tenant.id);
        verifyLatency(msg.timestamp, ts);
      },
    });
  }

  // Inject faults mid-test
  setTimeout(() => injectBrokerDrop(broker, 5), 30000);
  setTimeout(() => evictCacheKey(cache, /^tenant-a/), 45000);

  // Run traffic for all tenants in parallel
  await Promise.all(
    tenants.map(tenant => ingestEvents(tenant, msg => broker.publish(`${tenant.id}/events`, msg)))
  );

  // Final assertions
  console.log('All events processed. Verifying final state...');
  for (const tenant of tenants) {
    const storageData = await storage.getAll(tenant.id);
    assert.strictEqual(storageData.length, EVENTS_PER_SECOND * DURATION_SECONDS);
    console.log(`✓ ${tenant.name}: ${storageData.length} events stored`);
  }
}
```

## What to Look For in a Strong Answer
1. Clear test structure covering setup, execution, and assertions
2. Proper isolation verification at each layer (cache, broker, storage)
3. Realistic fault injection with measurable impact
4. Latency assertions tied to actual message timestamps
5. Reproducibility through seed data and deterministic traffic

